import{_ as a,o as s,c as e,ag as i}from"./chunks/framework.CvZZEx4j.js";const k=JSON.parse('{"title":"视觉特效","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/effects.md","filePath":"advanced/effects.md","lastUpdated":null}'),d={name:"advanced/effects.md"};function n(l,t,r,h,o,p){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="视觉特效" tabindex="-1">视觉特效 <a class="header-anchor" href="#视觉特效" aria-label="Permalink to &quot;视觉特效&quot;">​</a></h1><h2 id="特效列表" tabindex="-1">特效列表 <a class="header-anchor" href="#特效列表" aria-label="Permalink to &quot;特效列表&quot;">​</a></h2><p>插件基于 PixiJS 提供以下实时粒子特效：</p><table tabindex="0"><thead><tr><th>特效名</th><th>效果</th><th>适用场景</th></tr></thead><tbody><tr><td><code>rain</code></td><td>🌧️ 雨</td><td>雨天、忧郁场景</td></tr><tr><td><code>snow</code></td><td>❄️ 雪</td><td>冬天、宁静场景</td></tr><tr><td><code>heavySnow</code></td><td>🌨️ 大雪</td><td>暴风雪、严寒场景</td></tr><tr><td><code>cherryBlossoms</code></td><td>🌸 樱花飘落</td><td>春天、浪漫场景</td></tr><tr><td><code>fog</code></td><td>🌫️ 雾</td><td>神秘、恐怖场景</td></tr><tr><td><code>fireflies</code></td><td>✨ 萤火虫</td><td>夜晚、梦幻场景</td></tr><tr><td><code>embers</code></td><td>🔥 余烬</td><td>战斗、火灾场景</td></tr><tr><td><code>screenFlash</code></td><td>⚡ 闪屏</td><td>爆炸、雷电、强光</td></tr></tbody></table><h2 id="ai-自动触发" tabindex="-1">AI 自动触发 <a class="header-anchor" href="#ai-自动触发" aria-label="Permalink to &quot;AI 自动触发&quot;">​</a></h2><p>注入 COT 世界书后，AI 会根据剧情氛围在输出中自动插入特效标签。例如：</p><ul><li>下雨场景 → 自动触发 <code>rain</code> 特效</li><li>樱花树下 → 自动触发 <code>cherryBlossoms</code> 特效</li></ul><h2 id="画质等级" tabindex="-1">画质等级 <a class="header-anchor" href="#画质等级" aria-label="Permalink to &quot;画质等级&quot;">​</a></h2><p>在设置面板中可以调节特效画质：</p><ul><li><strong>高</strong>：粒子数量多，效果最佳，对设备性能要求较高</li><li><strong>平衡</strong>：推荐设置</li><li><strong>低</strong>：粒子数量少，适合低配设备</li></ul><h2 id="手动控制-进阶" tabindex="-1">手动控制（进阶） <a class="header-anchor" href="#手动控制-进阶" aria-label="Permalink to &quot;手动控制（进阶）&quot;">​</a></h2><p>你也可以通过浏览器控制台手动控制特效：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 播放特效</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">galgame.effects.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">play</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;rain&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 清除所有特效</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">galgame.effects.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clear</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 查看当前状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">galgame.effects.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">state</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div>`,13)])])}const g=a(d,[["render",n]]);export{k as __pageData,g as default};
